CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS admin_users(id INTEGER PRIMARY KEY, username TEXT UNIQUE, pw_hash TEXT);
CREATE TABLE IF NOT EXISTS media(
 id INTEGER PRIMARY KEY, filename TEXT, kind TEXT DEFAULT 'image', title TEXT DEFAULT '', caption TEXT DEFAULT '',
 category TEXT DEFAULT 'Eventi', show_home INTEGER DEFAULT 1, show_gallery INTEGER DEFAULT 1, show_intro INTEGER DEFAULT 0,
 featured INTEGER DEFAULT 0, hidden INTEGER DEFAULT 0, sort INTEGER DEFAULT 0, source TEXT DEFAULT '', placeholder INTEGER DEFAULT 0,
 created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS availability(id INTEGER PRIMARY KEY, weekday INTEGER, start TEXT, end TEXT);
CREATE TABLE IF NOT EXISTS closures(id INTEGER PRIMARY KEY, date TEXT, note TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS appointments(id INTEGER PRIMARY KEY, token TEXT UNIQUE, name TEXT, phone TEXT, email TEXT,
 event_type TEXT, event_date TEXT, notes TEXT, slot_date TEXT, slot_time TEXT, status TEXT DEFAULT 'in attesa',
 reminded INTEGER DEFAULT 0, consent INTEGER DEFAULT 0, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY, name TEXT, phone TEXT, email TEXT, event_type TEXT, event_date TEXT,
 place TEXT, guests TEXT, services TEXT, notes TEXT, status TEXT DEFAULT 'nuova', consent INTEGER DEFAULT 0,
 created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY, author TEXT, text TEXT, source TEXT, hidden INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY, name TEXT, phone TEXT, email TEXT, notes TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY, name TEXT, category TEXT, phone TEXT, email TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS equipment(id INTEGER PRIMARY KEY, name TEXT, category TEXT, qty INTEGER DEFAULT 1, status TEXT DEFAULT 'disponibile', notes TEXT);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, title TEXT, date TEXT, place TEXT, client_id INTEGER, notes TEXT);
CREATE TABLE IF NOT EXISTS event_equipment(id INTEGER PRIMARY KEY, event_id INTEGER, equipment_id INTEGER, qty INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY, kind TEXT, number TEXT, client_id INTEGER, date TEXT,
 items TEXT, total REAL DEFAULT 0, status TEXT DEFAULT 'bozza', notes TEXT);
CREATE TABLE IF NOT EXISTS journal(id INTEGER PRIMARY KEY, date TEXT, description TEXT, type TEXT DEFAULT 'entrata', amount REAL DEFAULT 0, notes TEXT);
CREATE TABLE IF NOT EXISTS calls(id INTEGER PRIMARY KEY, from_number TEXT, transcript TEXT, payload TEXT, created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS team(id INTEGER PRIMARY KEY, name TEXT, role TEXT DEFAULT '', phone TEXT DEFAULT '', email TEXT DEFAULT '', note TEXT DEFAULT '', visible TEXT DEFAULT 'si', sort INTEGER DEFAULT 0, notify TEXT DEFAULT 'si', on_duty TEXT DEFAULT 'no');
CREATE TABLE IF NOT EXISTS stats_events(id INTEGER PRIMARY KEY, ts TEXT DEFAULT CURRENT_TIMESTAMP, day TEXT, kind TEXT, ref TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS ev_day_kind ON stats_events(day, kind);
CREATE TABLE IF NOT EXISTS report_log(id INTEGER PRIMARY KEY, key TEXT UNIQUE, kind TEXT, sent_at TEXT DEFAULT CURRENT_TIMESTAMP, ok INTEGER DEFAULT 0, tries INTEGER DEFAULT 0, detail TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS wa_log(id INTEGER PRIMARY KEY, ts TEXT DEFAULT CURRENT_TIMESTAMP, to_num TEXT, kind TEXT, ok INTEGER, detail TEXT);
CREATE TABLE IF NOT EXISTS secrets(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY, ts TEXT DEFAULT CURRENT_TIMESTAMP, user_id INTEGER, username TEXT DEFAULT '', role TEXT DEFAULT '', action TEXT, detail TEXT DEFAULT '', ip TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS audit_ts ON audit_log(ts);
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY, number TEXT, year INTEGER, seq INTEGER, client_id INTEGER, client_name TEXT DEFAULT '', client_addr TEXT DEFAULT '',
 client_piva TEXT DEFAULT '', client_cf TEXT DEFAULT '', client_sdi TEXT DEFAULT '', client_pec TEXT DEFAULT '', issue_date TEXT, due_date TEXT, status TEXT DEFAULT 'bozza',
 items TEXT DEFAULT '[]', imponibile REAL DEFAULT 0, iva_pct REAL DEFAULT 22, iva REAL DEFAULT 0, total REAL DEFAULT 0, notes TEXT DEFAULT '',
 source_type TEXT DEFAULT '', source_id INTEGER, event_id INTEGER, sdi_status TEXT DEFAULT 'non inviata', sdi_note TEXT DEFAULT '', created TEXT DEFAULT CURRENT_TIMESTAMP, created_by TEXT DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS ux_invoice_number ON invoices(number) WHERE number IS NOT NULL AND number != '';
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, date TEXT, amount REAL DEFAULT 0, method TEXT DEFAULT 'bonifico', note TEXT DEFAULT '',
 invoice_id INTEGER, document_id INTEGER, event_id INTEGER, created TEXT DEFAULT CURRENT_TIMESTAMP, created_by TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS pay_date ON payments(date);
CREATE TABLE IF NOT EXISTS tariffe(id INTEGER PRIMARY KEY, name TEXT, category TEXT DEFAULT 'Altro', service TEXT DEFAULT '', unit TEXT DEFAULT 'a evento',
 price REAL DEFAULT 0, note TEXT DEFAULT '', active INTEGER DEFAULT 1, public INTEGER DEFAULT 0, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS day_notes(date TEXT PRIMARY KEY, note TEXT DEFAULT '', updated TEXT DEFAULT CURRENT_TIMESTAMP, user TEXT DEFAULT '');
